 "content": "from collections import deque


def transform(grid):
    """Replace a 3x3 neighborhood around each marker inside a 3-panel with 1s."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if g[r][c] != 3 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] == 3 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            components.append(comp)

    # Each panel is a filled rectangular field of 3s with some 2 markers
    # punched into it. Its 3-components have the panel's bounding rectangle.
    panels = []
    for comp in components:
        r0 = min(r for r, _ in comp)
        r1 = max(r for r, _ in comp)
        c0 = min(c for _, c in comp)
        c1 = max(c for _, c in comp)
        if (r1 - r0 + 1) * (c1 - c0 + 1) > 4:
            box = (r0, r1, c0, c1)
            if box not in panels:
                panels.append(box)

    centers = set()
    for r0, r1, c0, c1 in panels:
        for r in range(r0, r1 + 1):
            for c in range(c0, c1 + 1):
                if g[r][c] == 2:
                    centers.add((r, c))
    for r, c in centers:
        for y in range(max(0, r - 1), min(h, r + 2)):
            for x in range(max(0, c - 1), min(w, c + 2)):
                if (y, x) not in centers:
                    g[y][x] = 1
        g[r][c] = 2
    return g


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
